#include "global.h"

#if _XBOX
#include "xbglobals.h"
#endif

#include "FrontEndManager.h"
#include "BoardFrontEnd.h"
#include "unlock_manager.h"

extern game* g_game_ptr;

void BoardFrontEnd::Draw()
{
	if(wait_for_camera) return;
	if(arrow_counter >= 0) arrow_counter--;
	if(arrow_counter < 0 && arrow_counter > -5)
	{
		arrow_counter = -5;
		arrows[0][0]->TurnOn(true);
		arrows[0][1]->TurnOn(false);
		arrows[1][0]->TurnOn(true);
		arrows[1][1]->TurnOn(false);
	}

	FEMultiMenu::Draw();

	// says "LOCKED" if not unlocked
	board_stats->Draw();

	if(unlocked)
	{
		for(int i=0; i<4; i++)
		{
			gauge_labels[i]->Draw();
			top_gauge_labels[i]->Draw();
			red_gauges[i]->Draw(0);
		}

		height->Draw();
		width->Draw();
		thick->Draw();
		tail->Draw();
		height_label->Draw();
		width_label->Draw();
		thick_label->Draw();
		tail_label->Draw();
		comb_stats->Draw();
	}

	if(sys->multiplayer)
	{
		if(sys->multi_1) players[0]->Draw();
		else players[1]->Draw();
	}
	else header->Draw();
}
